UPDATE inventory_sync_run_source
   SET read_count = #{readCount}, mapped_count = #{mappedCount}
 WHERE inventory_sync_run_id = #{runId} AND source_type = #{sourceType}

UPDATE inventory_sync_run_source
   SET end_version = #{endVersion}, source_status = #{status}, completed_at = SYSTIMESTAMP
 WHERE inventory_sync_run_id = #{runId} AND source_type = #{sourceType}

UPDATE inventory_sync_run_source
   SET changed_count = changed_count + #{changedCount}
 WHERE inventory_sync_run_id = #{runId} AND source_type = #{sourceType}
